package io.github.davamix.workouttimer.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.MediaPlayer
import io.github.davamix.workouttimer.R

/**
 * A [SoundPlayer] that plays `res/raw/round_end.wav`, generated by `tools/generate-round-end-sound.ps1` (plan D-10),
 * with one [MediaPlayer] kept for the life of the app.
 *
 * It plays at the media volume, like the voice (specification §5.3). Problems never throw: they go to [onWarning],
 * and `onDone` is called at once. After an error the player is released, and the next call loads it again.
 *
 * @param onWarning Called with a message, and the error if there is one, for every problem.
 */
class MediaSoundPlayer(
    context: Context,
    private val onWarning: (message: String, error: Throwable?) -> Unit = { _, _ -> },
) : SoundPlayer {
    private val context = context.applicationContext

    // Guarded by lock.
    private val lock = Any()
    private var player: MediaPlayer? = null
    private var pendingDone: (() -> Unit)? = null

    override fun prepare() {
        synchronized(lock) { loadLocked() }
    }

    override fun playRoundEnd(onDone: () -> Unit) {
        var cutOff: (() -> Unit)? = null
        var started = false
        synchronized(lock) {
            val player = loadLocked()
            cutOff = pendingDone
            pendingDone = null
            if (player != null) {
                try {
                    player.seekTo(0)
                    player.start()
                    pendingDone = onDone
                    started = true
                } catch (e: IllegalStateException) {
                    onWarning("Can't play the round-end sound", e)
                    releaseLocked()
                }
            }
        }
        cutOff?.invoke()
        if (!started) onDone()
    }

    /** The loaded player, loading it if needed, or `null` if it can't be loaded. */
    private fun loadLocked(): MediaPlayer? {
        player?.let { return it }
        val created =
            try {
                MediaPlayer.create(context, R.raw.round_end, AUDIO_ATTRIBUTES, audioSessionId())
            } catch (e: RuntimeException) {
                onWarning("Can't load the round-end sound", e)
                return null
            }
        if (created == null) {
            onWarning("Can't load the round-end sound", null)
            return null
        }
        created.setOnCompletionListener { finished() }
        created.setOnErrorListener { _, what, extra ->
            onWarning("Round-end sound failed (what=$what, extra=$extra)", null)
            synchronized(lock) { releaseLocked() }
            finished()
            true
        }
        player = created
        return created
    }

    private fun releaseLocked() {
        player?.release()
        player = null
    }

    /** The chime finished, or failed: calls its `onDone`, once. */
    private fun finished() {
        val done = synchronized(lock) { pendingDone.also { pendingDone = null } }
        done?.invoke()
    }

    private fun audioSessionId(): Int =
        context.getSystemService(AudioManager::class.java)?.generateAudioSessionId() ?: AudioManager.AUDIO_SESSION_ID_GENERATE

    private companion object {
        val AUDIO_ATTRIBUTES: AudioAttributes =
            AudioAttributes
                .Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
    }
}
